function UICultivateEquipIntroductionNodeMB:RefreshUI(params, equipType, playerCardId, isHideLockBtn)
    xTry(function()
        self.params, self.equipType, self.playerCardId = params, equipType, checkNumber(playerCardId)

        local isEquip = equipType == EquipType.Equip
        local isCore  = equipType == EquipType.Core
        KTool.SetActive(self.AttrNodes.gameObject, isEquip)
        KTool.SetActive(self.Part.gameObject, isEquip)
        KTool.SetActive(self.ScrollView.gameObject, isCore)
        KTool.SetActive(self.Core.gameObject, isCore)


        if isEquip then
            self:RefreshEquipUI(params, isHideLockBtn)
        elseif isCore then
            self:RefreshEquipCoreUI(params, isHideLockBtn)
        end

    end)
end

function UICultivateEquipIntroductionNodeMB:RefreshEquipUI(params, isHideLockBtn)
    ---@type EquipDojo
    local dojo = params.dojo
    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    self:RefreshEquipNode(equipVo, dojo)

    self:RefreshCommonUI(dojo, dojo.equipmentId, params.status, isHideLockBtn)

    self:RefreshAllAttrNode(dojo, equipVo)
end

---RefreshEquipNode
---@param equipVo EquipVo
---@param equipDojo EquipDojo
function UICultivateEquipIntroductionNodeMB:RefreshEquipNode(equipVo, equipDojo)
    local part = equipVo.part
    self.PartText.text = string.format("0%s", part)
    self.LevelText.text = equipDojo.level
    self:RefreshEquipHeadNode(equipDojo, part)
end


function UICultivateEquipIntroductionNodeMB:RefreshEquipHeadNode(equipDojo, part)
    ---@type UICultivateEquipHeadNode
    local env = CfUtils.GetLuaScr(self.EquipPartNode, EquipHeadNodeEnvPath)
    if isNull(env) then
        return
    end
    env:RefreshUI(equipDojo, part, false)
end

function UICultivateEquipIntroductionNodeMB:RefreshEquipCoreUI(params, isHideLockBtn)
    ---@type EquipmentCoreDojo
    local dojo = params.dojo
    local equipDojoList = params.equipDojoList
    local status = params.status

    local equipmentCoreId = dojo.equipmentCoreId
    ---@type EquipCoreVo
    local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreId)
    ---@type GoodsVo
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipmentCoreId)

    self:RefreshCoreNode(goodsVo, equipCoreVo.occupationId)
    self:RefreshCommonUI(dojo, dojo.equipmentCoreId, status, isHideLockBtn)
    self:RefreshSuitDesc(dojo, equipDojoList)
    --self:RefreshExclusiveGroup(status, equipCoreVo.occupationId, lastActiveIndex)

end

---RefreshCoreNode
---@param goodsVo GoodsVo
---@param occupationId number
function UICultivateEquipIntroductionNodeMB:RefreshCoreNode(goodsVo, occupationId)
    local isShow = occupationId > 0
    KTool.SetActive(self.ExclusiveText.gameObject, isShow)
    if isShow then
        ---@type JobVo
        local jobVo = cardConfMgr:GetCardCareerRowByType(occupationId)
        self.ExclusiveText.text = jobVo.name
    end

    self.CoreIcon:LoadSprite(goodsVo.photoPath)
    self.CoreQuality.Status = goodsVo.quality
end

function UICultivateEquipIntroductionNodeMB:RefreshCommonUI(dojo, goodsId, status, isHideLockBtn)
    self:RefreshName(goodsId)
    self:RefreshCardTip(dojo)
    self:RefreshLockBtn(checkNumber(dojo.locked), status, isHideLockBtn)
    self:RefreshBottomNode(status, dojo)

end

function UICultivateEquipIntroductionNodeMB:RefreshCardTip(dojo)
    local playerCardId = checkNumber(dojo.playerCardId)
    local isInstall = playerCardId > 0
    KTool.SetActive(self.Worn.gameObject, isInstall)
    KTool.SetActive(self.NotWorn.gameObject, not isInstall)
    if isInstall then

        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(playerCardId)
        local cardSkin = cardDojo.cardSkin
        ---@type CardSkinVo
        local skinVo = cardConfMgr:GetCardSkinBySkinId(cardSkin)
        self.ImgRoleHead:LoadSprite(skinVo.buffHead)
        self.TextName.text = skinVo.name

        self.ImgStatusWorn.Status = (self.playerCardId > 0 and self.playerCardId == playerCardId) and 2 or 1

    end
end

function UICultivateEquipIntroductionNodeMB:RefreshEquipOrCoreNode(dojo, goodsId)
    self:RefreshGoodNode(self.EquipNode, dojo, goodsId)
end

function UICultivateEquipIntroductionNodeMB:RefreshCardNode(playerCardId)
    local isShowCardNode = playerCardId > 0
    KTool.SetActive(self.CardNode.gameObject, isShowCardNode)
    KTool.SetActive(self.CardTipImage.gameObject, isShowCardNode)

    if isShowCardNode then
        local cardDojo = cardComp:GetCardById(playerCardId)
        self:RefreshGoodNode(self.CardNode, cardDojo, cardDojo.cardId)
    end

end

---RefreshName
---@param goodsId number 道具id
function UICultivateEquipIntroductionNodeMB:RefreshName(goodsId)
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    local name    = goodsVo.name
    self.NameText.text = name

end

function UICultivateEquipIntroductionNodeMB:RefreshLockBtn(locked, status, isHideLockBtn)
    local isShow = status ~= Status.Preview and isHideLockBtn ~= true
    KTool.SetActive(self.LockBtn.gameObject, isShow)
    if isShow then
        self.LockBtn.Status = locked == 0 and 1 or 2

    end
end

---RefreshAllAttrNode
---刷新副属性列表
---@param equipDojo EquipDojo
---@param equipVo EquipVo
function UICultivateEquipIntroductionNodeMB:RefreshAllAttrNode(equipDojo, equipVo)
    
    -- local childCount   = attrNodes.childCount
    ---@type EquipQualityVo
    local equipQualityVo = cardConfMgr:GetEquipQualityVoByRefId(equipVo.rare)
    self:RefreshMainAttr(equipDojo)

    -- local maxNum = equipQualityVo.maxNum
    -- if childCount > maxNum then
    --     for i = maxNum + 1, childCount do
    --         KTool.SetActive(attrNodes:GetChild(i - 1).gameObject, false)
    --     end
    -- end
    local loopTimes = equipQualityVo.maxNum
    local baseAttrCount = EquipUtils.GetBaseAttrCount(equipDojo, equipVo, equipQualityVo)
    local overMax = equipQualityVo.overMax
    local baseLv = equipQualityVo.baseLv
    local attrNodes = self.AttrNodes
    local attrNode = self.AttrNode
    for i = 1, loopTimes do
        local go = self.subAttrNodes[i]
        if go == nil then
            go = attrNodes.gameObject:AddChild(attrNode.gameObject)
            self.subAttrNodes[i] = go
        end
        KTool.SetActive(go.gameObject, true)
        local unlockAttrLevel = baseLv + overMax * (i - baseAttrCount)
        -- if i > 1 then
        --     unlockAttrLevel = baseLv + overMax * (i - 1 - baseAttrCount)
        -- end
        self:RefreshAttrNode(go, equipDojo, i, unlockAttrLevel)
    end
end

function UICultivateEquipIntroductionNodeMB:RefreshMainAttr(equipDojo)
    local attrAdditionId = checkNumber(equipDojo.mainAttrId)
    local attrNum        = equipDojo.mainAttrNum
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)
    local basicVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(attrAdditionId)
    self.AttrNameText.text = basicVo.name
    self.AttrNumText.text = attribute_format(attrAdditionVo.isConversion, attrNum)
end

---RefreshSubAttrNode
---@param subAttrNode UnityEngine.Transform 副属性节点
---@param equipDojo EquipDojo
---@param index number
---@param unlockAttrLevel number 多少级解锁
function UICultivateEquipIntroductionNodeMB:RefreshAttrNode(subAttrNode, equipDojo, index, unlockAttrLevel, isMainAttr)
    ---@type UICultivateSubAttrNodeNode
    local env = CfUtils.GetLuaScr(subAttrNode.gameObject, SubAttrNodeNodePath)
    local unlockTipText = localize("Lv_num_解锁", {_num_ = unlockAttrLevel})
    env:RefreshUI(equipDojo, index, unlockTipText, isMainAttr)
    env:RefreshBackgroundShowState(index % 2 ~= 0)

end

function UICultivateEquipIntroductionNodeMB:RefreshSuitDesc(dojo, equipDojoList)

    local equipmentCoreId   = dojo.equipmentCoreId
    local curEquipListSuitInfo = equipDojoList and EquipUtils.GetEquipSuitInfoByEquipDojoList(equipDojoList) or {}
    local suitEffectList, lastActiveIndex = EquipUtils.GetAllSuitEffectList(equipmentCoreId, curEquipListSuitInfo)

    self.suitEffectList = suitEffectList
    self.lastActiveIndex = lastActiveIndex
    local count = #suitEffectList
    local ScrollView = self.ScrollView
    if not ScrollView.IsListViewInit then
        ScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(ScrollView, count)
    end
    return lastActiveIndex
end


---OnGetItemByIndex
---随从列表刷新回调
---@param listView SuperScrollView.LoopListView2 列表对象
---@param index number c#中的index
---@return SuperScrollView.LoopListViewItem2
function UICultivateEquipIntroductionNodeMB:OnGetItemByIndex(listView, index)
    local position = index + 1
    if position < 1 then
        return nil
    end

    -- 创建cell
    local cell = listView:NewListViewItem(PrefabNameDescNode)
    if not KTool.IsNull(cell) then
        --- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabMBDescNodePath)
        if not KTool.IsNull(cellViewMB) then
            ---@type UICultivateEquipIntroductionDescNodeMB
            local mbEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
            end

            local suitEffectData = self.suitEffectList[position]
            if mbEnv then
                mbEnv:RefreshUI(suitEffectData, position, self.lastActiveIndex, self.params.iShowCanActive)
            end

        end
    end

    return cell
end

function UICultivateEquipIntroductionNodeMB:RefreshBottomNode(status, dojo)
    local isPreview = status == Status.Preview
    KTool.SetActive(self.BottomNode.gameObject, not isPreview)
    if isPreview then return end
    local conf = StatusConf[status]
    local isShowBtn = conf ~= nil and next(conf) ~= nil
    KTool.SetActive(self.BottomButtons.gameObject, isShowBtn)
    KTool.SetActive(self.FontStyleButton.gameObject, status == Status.Installed)
    if isShowBtn then
        local left          = conf.left
        local isShowLeftBtn = left ~= nil
        KTool.SetActive(self.LeftButton.gameObject, isShowLeftBtn)

        if isShowLeftBtn then
            local text, styleId = SafeUnpack(left)

            --- 只有装备可能会显示 eft btn
            local level = checkNumber(dojo.level)
            local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
            local maxLevel = cardConfMgr:GetEquipMaxLevelByQuality(equipVo.rare)
            local isMaxLevel = level == maxLevel
            if isMaxLevel then
                text, styleId = localize("已满级"), "B22"
            else
                text, styleId = SafeUnpack(left)
            end

            self.LeftButton:ResetFontStyle(styleId, text)
            self.isMaxLevel = isMaxLevel
            --KTool.SetActive(self.LeftButton.gameObject, not isMaxLevel)
            --KTool.SetActive(self.TxtMax.gameObject, isMaxLevel)
        else
            self.isMaxLevel = false
            --KTool.SetActive(self.TxtMax.gameObject, false)
            --KTool.SetActive(self.LeftButton.gameObject, false)
        end

        local right          = conf.right
        local isShowRightBtn = right ~= nil
        KTool.SetActive(self.RightButton.gameObject, isShowRightBtn)
        if isShowRightBtn then
            local text, styleId = SafeUnpack(right)
            self.RightButton:ResetFontStyle(styleId, text)
        end
    end

end

---RefreshGoodNode
---刷新道具节点
---@param goodNode UnityEngine.Transform 道具节点
---@param id number 数据库id
---@param goodsId number 道具id
function UICultivateEquipIntroductionNodeMB:RefreshGoodNode(goodNode, dojo, goodsId)
    local mbEnv = CfUtils.GetLuaScr(goodNode, GoodNodeMBPath)
    if mbEnv == nil then return end
    mbEnv:Reload({dojo = dojo, goodsId = goodsId})
end


